def prepare():
    paths=['docs/adr/ADR-0090-governed-offline-field-proof-exclusive-capability-composition.md','docs/specifications/SPEC-0090-governed-offline-field-proof-exclusive-capability-composition.md','docs/evidence/package-0090-full-reachable-expectation-closure/return-tuple-expectation.json','docs/evidence/package-0090-full-reachable-expectation-closure/provider-attmap.c','docs/evidence/package-0090-full-reachable-expectation-closure/flyway-history-constructor-template.txt']
    freeze=json.loads((c.OUT/'source-freeze.json').read_text())
