    for name in ['target-1','target-2']:
        folder=c.OUT/name; runtime=json.loads((folder/'foundation-runtime.json').read_text())
        candidate=json.loads((folder/'candidate-runtime.json').read_text()); raw=json.loads((folder/'return-tuple-runtime.json').read_text())
        q.require(not runtime['errors'] and runtime['owned_runtime_destroyed'],'Runtime failure or cleanup incomplete')
        q.require(len(candidate['cases'])==10 and all(x['passed'] for x in candidate['cases']) and all(x['passed'] for x in raw['cases']),'Candidate/raw proof incomplete')
        for filename,h in runtime['recipe_hashes'].items(): q.require(q.sha((q.ROOT/'scripts/validation'/filename).read_bytes())==h,'Runtime recipe drift')
        raw_errors={x['name']:x['details'] for x in raw['cases']}
        raw_report=dict(target=runtime['isolation'],raw_shape_sqlstate=raw['isolated_error']['sqlstate'],version_sqlstate=raw_errors['text_result_mismatch_version']['sqlstate'],type_sqlstate=raw_errors['text_result_mismatch_type']['sqlstate'],script_sqlstate=raw_errors['text_result_mismatch_script']['sqlstate'],canonical_S04_executed=False)
        candidate_report=dict(target=runtime['isolation'],candidate_sqlstate=candidate['candidate']['sqlstate'],rows=len(candidate['candidate']['rows']),exact_history_match=True,delivered_ranks=candidate['candidate']['delivered_ranks'],corrected_types=candidate['corrected_types'],proof=candidate,canonical_S04_executed=False)
        suffix=name.split('-')[-1]
        c.save('raw-defect-target-'+suffix+'.json',raw_report); c.save('candidate-target-'+suffix+'.json',candidate_report)
        runs.append(dict(raw=raw_report,candidate=candidate_report,cleanup=runtime['cleanup']))
    one,two=runs
    q.require(one['raw']['target']['id']!=two['raw']['target']['id'] and one['raw']['target']['volume']!=two['raw']['target']['volume'],'Targets not independent')
    q.require(one['candidate']['proof']['candidate']==two['candidate']['proof']['candidate'] and one['raw']['raw_shape_sqlstate']==two['raw']['raw_shape_sqlstate']=='42804','Candidate not reproducible')
    c.save('null-semantics.json',dict(changed=False,assertions=[next(x for x in r['candidate']['proof']['cases'] if x['name']=='NULL_preserved') for r in runs]))
    c.save('content-equivalence.json',dict(changed=False,comparison='varcharsend(original) IS NOT DISTINCT FROM textsend(qualified_cast) for each textual field on all 42 rows',targets=[[x for x in r['candidate']['proof']['cases'] if x['name'].startswith('candidate_type_and_binary_content_')] for r in runs],encoding='UTF8'))
    c.save('ordering-equivalence.json',dict(changed=False,source_ORDER_BY_AST_unchanged=True,observed_delivery_ordinals=[r['candidate']['delivered_ranks'] for r in runs],expected=list(range(1,43)),not_established_by_sorting_by_rank=True))
    c.save('search-path-cast-proof.json',dict(dependent=False,shadowing_pass=True,contexts=[r['candidate']['proof']['shadow_proof'] for r in runs],shadow_types=['pg_temp.text','public.text'],search_path='pg_temp,public,pg_catalog',qualified_target='pg_catalog.text',expected_provider_type_oid=25,public_shadow_types_removed=True,scope='Type-cast/helper only; no S04 security negative claim'))
    canonical=q.git('show',c.BASELINE+':'+q.V043.relative_to(q.ROOT).as_posix())
    q.require(q.sha(canonical)==q.SOURCE_HASH and q.V043.read_bytes().replace(b'\r\n',b'\n')==canonical,'Canonical changed')
    q.require(q.git('ls-files','--stage',q.V043.relative_to(q.ROOT).as_posix()).decode().split()[1]==json.loads((c.OUT/'source-freeze.json').read_text())['current_git_blob'],'Canonical index changed')
    for p in q.MIGRATIONS.glob('V*.sql'):
        if int(p.name.split('__')[0][1:])<=42: q.require(p.read_bytes().replace(b'\r\n',b'\n')==q.git('show',q.FROZEN+':'+p.relative_to(q.ROOT).as_posix()),'Frozen migration changed')
    c.save('READINESS.json',dict(source_correction_candidate_ready=True,canonical_source_mutated=False,correction_authority_granted=False,return_tuple_fix_reproducible=True,executed_canonical_S04=False,corrected_S04_executed=False,only_pg_temp_helpers_executed=True,readiness_created=False,expression_190_closure_continued=False,mutation_denominator_derived=False,T10_fence_implemented=False,canonical_V043_executed=False,shared_db_contacted=False,production_contacted=False,execution_authority='BLOCKED',recovery_authority='BLOCKED',room_operational=False,new_candidate_cases=10,reused_raw_compatibility_cases=9,reused_foundation_cases=93,accepted_cases_per_target=112,accepted_failures=0,physical_line_count_deviation='Three expressions on one pre-existing line: 1 removed and 1 added line, not 3 physical lines',explicit_authority_needed_for_later_application=True))
    hashes=json.loads((c.OUT/'candidate-source-hash.json').read_text()); impact=json.loads((c.OUT/'migration-impact.json').read_text()); consumers=json.loads((c.OUT/'consumer-search.json').read_text())
    report=q.ROOT/'docs/evidence/PACKAGE-0090-S04-return-tuple-correction-candidate.md'
    report.write_text('''# Package 0090 S04 return-tuple correction candidate\n\nSOURCE_CORRECTION_CANDIDATE_READY=YES. This is a proved, frozen candidate only. Canonical V043 was neither written, staged, committed nor executed. The patch was generated from frozen Git-LF bytes, applied only in memory for hashes/AST comparison, and checked read-only with git apply --check --cached; the actual index entry remained unchanged. No corrected or original S04 invocation, READY or authority promotion occurred.\n\nThe correction adds exactly ::pg_catalog.text to h.version, h.type and h.script in the existing RETURN QUERY. All three expressions occupy ONE physical source line. Therefore the exact minimal patch replaces one line, with three expression changes; reporting three physical changed lines would be false, and reformatting to force that count would add forbidden whitespace churn. No other source bytes change. The API/attributes outside the body are AST-identical, and the SELECT trees differ only by the three expected TypeCast nodes. Removing those nodes recovers the exact prior SELECT; reversing the one source replacement recovers the entire prior V043 byte-for-byte, including the fence, exceptions, guards, owner and ACL statements.\n\nTwo fresh owned PostgreSQL 18.4 targets reproduced raw 42804 for the full projection and each version/type/script position. The QUALIFIED candidate pg_temp helper returned 00000 and exactly the independent 42 six-field history rows on both targets. WITH ORDINALITY retained actual helper delivery order 1..42 rather than sorting results to manufacture order. All three outputs are exactly pg_catalog.text; raw varchar and candidate text binary-send payloads matched on every row under UTF8. NULL remained NULL.\n\nBoth targets created pg_temp.text and public.text composite shadow types and put pg_temp,public before pg_catalog in search_path. Unqualified text resolved to a different OID, proving the lure was effective, while the three qualified casts still resolved to provider text OID 25 and the candidate helper returned exactly 42 rows. Public shadow types were removed; temporary helpers/types vanished with their own sessions; both owned targets and credentials were destroyed. These are candidate type/tuple proofs, not S04 authorization or security-negative runtime tests.\n\nTen new candidate assertions per target passed, with nine reused raw compatibility and 93 reused foundation assertions (112 per target), using normal Python and Python -O. Static source/API/SELECT/inverse/index/applicability assertions also passed. There were no accepted runtime failures. No Kotlin/Java code changed; consumer inspection is not represented as an executed S04 application test.\n\nThe exact correction implements the already intended contract: SPEC-0090 sections 21.1/S04 and lines 284,314–320,819 declare text outputs and unchanged history ordering; ADR-0090 auditor/history authority stays unchanged. The section21.7 inventory is output/type traceability, not authority to change Flyway columns. No ADR or SPEC amendment is required for these three casts. No normative document was edited. The narrower-character unqualified ::text is expressly rejected because it is search-path dependent; CAST(... AS pg_catalog.text) is equivalent but longer; changing the return API or Flyway columns is forbidden and broader.\n\nThe source hash and future Flyway checksum DO change if the candidate is later adopted. This does not authorize migration mutation or repair. Current qualification evidence shows no canonical migration application; shared/production execution history was not independently queried. Before adoption, explicit source authority and release coordination must rebaseline source/body/derived qualification hashes, AST/semantic/currentness/ACL/native fixtures and release records; old source-hash validators correctly remain pinned now. The fence is retained. No 190-site work or T10 work continued.\n\nThe three direct S04 application/test consumer files retain the same arguments and six-column contract; GovernedJdbc.history reads the three textual positions with getString. Broader history readers, baseline tests and validation/hash consumers are listed separately. No downstream public contract break is expected; generated source/body/AST identity expectations do require coordinated refresh after authority. No consumers were modified.\n\nNEXT, not executed: obtain explicit authority to apply exactly the frozen three-expression patch. Candidate readiness is not mutation authority.\n''',encoding='utf-8')
    report.write_text(report.read_text(encoding='utf-8')+'\nFrozen current Git-LF SHA256: '+hashes['current']+'\n\nHypothetical candidate Git-LF SHA256: '+hashes['hypothetical_candidate']+'\n\nComputed future Flyway CRC32: '+str(impact['old_Flyway_signed_CRC32'])+' -> '+str(impact['candidate_Flyway_signed_CRC32'])+'\n\nDirect S04 consumer files: '+str(consumers['direct_count'])+'; broader history files: '+str(consumers['broader_count'])+' (overlap retained).\n',encoding='utf-8')
    inputs={p.relative_to(q.ROOT).as_posix():q.sha(p.read_bytes()) for p in [Path(__file__),Path(c.__file__),Path(c.raw.__file__),q.ROOT/'scripts/validation/package_0090_active_foundation.py']}
    outputs={p.relative_to(q.ROOT).as_posix():q.sha(p.read_bytes()) for p in sorted(c.OUT.rglob('*')) if p.is_file() and p.name!='SHA256-MANIFEST.json'}
    outputs[report.relative_to(q.ROOT).as_posix()]=q.sha(report.read_bytes())
    c.save('SHA256-MANIFEST.json',dict(inputs=inputs,outputs=outputs,baseline=c.BASELINE,current_canonical_git_lf_sha256=q.SOURCE_HASH,candidate_git_lf_sha256=hashes['hypothetical_candidate']))
    print(json.dumps(dict(candidate_ready=True,reproducible=True,canonical_unchanged=True,physical_source_lines_replaced=1,source_expressions_changed=3,candidate_cases_per_target=10,accepted_cases_per_target=112,direct_consumers=consumers['direct_count'],history_consumers=consumers['broader_count'])))


